local GachaponSkinBlendDialog = Class('GachaponSkinBlendDialog')
local CommonCurrencyNode = "Game.Behaviours.CommonCurrencyNode"
local DrawType = {
	One = 1,
	Ten = 2,
}

function GachaponSkinBlendDialog:__init()
	self.nodePrefab = nil
end

function GachaponSkinBlendDialog:__delete()
	if self.nodePrefab then
		CfUtils.SafeDelete(self.nodePrefab)
		self.nodePrefab = nil
	end
end

function GachaponSkinBlendDialog:Awake()
	self:AddUiClick()
end

function GachaponSkinBlendDialog:AddUiClick()
	SetButtonAction(self.BtnOneNode.gameObject,Bind(self,self.OnBtnOneNodeClick))
	SetButtonAction(self.BtnTenNode.gameObject,Bind(self,self.OnBtnTenNodeClick))
	SetButtonAction(self.BtnMember.gameObject,Bind(self,self.OnBtnMemberClick))
	SetButtonAction(self.BtnStore.gameObject,Bind(self,self.OnBtnStoreClick))
end

function GachaponSkinBlendDialog:RefreshData(skinData)
	self.activityData = skinData
	self:SetTimeShow()
	GameUtils.Request(Interfaces.ActivitySkinShow,{activityUuid = self.activityData.id},function(request,response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			self.skinData = responseData
			self:RefreshUI()
		end
	end)
end

function GachaponSkinBlendDialog:RefreshUI()
	self:RefreshBtnNode()
	self:RefreshBtnShoW()
	self:RefreshDesc()
end

function GachaponSkinBlendDialog:RefreshDesc()
	if not string.isEmpty(checkString(self.skinData.desc)) then
		CfUtils.FillText(self.TxtInstructions, string.gsub(self.skinData.desc,"_num_",self.skinData.leftGuaranteedTimes))
	end
end

function GachaponSkinBlendDialog:RefreshBtnNode()
	local subPrefab = self.skinData.subPrefab
	if not string.isEmpty(subPrefab) and not self.nodePrefab then
		local path = string.format("Prefabs/GachaponSkin/%s.prefab", self.skinData.subPrefab)
		ResourceModule.LoadBundleAsync(path, function (loader, ok, resultObject)
			if ok then
				local go = loader:Instantiate(self.RolePanel.transform, false)
				if isNotNull(go) then
					local t = go:GetComponent(typeof(RectTransform))
					t.anchorMin = Vector2.zero
					t.anchorMax = Vector2.one
					t.offsetMin = Vector2.zero
					t.offsetMax = Vector2.zero
					t.localPosition = Vector3.zero
					t.localRotation = Quaternion.identity
					t.localScale = Vector3.one
					go:SetActive(false)
					self.nodePrefab = go
					self:RefreshRoleShow()
					CfUtils.SetActive(go.gameObject,true)
				end
			end
			loader:Release()
		end, true )
	else
		self:RefreshRoleShow()
	end
end

function GachaponSkinBlendDialog:RefreshRoleShow()
	local env = CfUtils.GetLuaScr(self.nodePrefab,"Game.Activity.GachaponSkin.GachaponSkinBlendRoleNode")
	if isNotNull(env) then
		env:RefreshRoleNodeShow(self.skinData.modelIds)
	end
end

function GachaponSkinBlendDialog:RefreshBtnShoW()
	local oneBtnEnv = CfUtils.GetLuaScr(self.BtnOneConsumePop, CommonCurrencyNode)
	if isNotNull(oneBtnEnv) then
		oneBtnEnv:SetCurrencyShow(self.skinData.oneConsume.goodsId, self.skinData.oneConsume.num)
	end
	
	local tenBtnEnv = CfUtils.GetLuaScr(self.BtnTenConsumePop, CommonCurrencyNode)
	if isNotNull(tenBtnEnv) then
		tenBtnEnv:SetCurrencyShow(self.skinData.tenConsume.goodsId, self.skinData.tenConsume.num)
	end
end

function GachaponSkinBlendDialog:SetTimeShow()
	local ActivityUtils         = import("Game.Activity.ActivityUtils")
	CfUtils.FillText(self.DurationTime, ActivityUtils.ConventActivityDurationTime(self.activityData.startTime, self.activityData.closeTime))
end

function GachaponSkinBlendDialog:OnBtnDraw(drawType)
	GameUtils.Request(Interfaces.ActivitySkinShowCall,{activityUuid = self.activityData.id,type = drawType},function(request,response)
		if checkNumber(response.errCode) == 0 then
			local consumeData = drawType == DrawType.One and self.skinData.oneConsume or self.skinData.tenConsume
			GoodsUtils.DrawRewards({ { goodsId = consumeData.goodsId, num = -consumeData.num } }, false)
			local responseData = response.data
			if table.count(responseData.rewards) > 0 then
				self:DrawRewards(responseData.rewards)
				CfUtils.StartCoroutineWithBlocker(function()
					self:PlayNormalTimeLine("gacha_siknshow",Bind(self,function()
						CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.GachaponSkinBlendResultDialog, parameters = { rewards = responseData.rewards } },
								{{id = Constants.UITypeIds.ActivityGachaponSkinDialog}})
					end))
				end)
			end
		end
	end)
end

function GachaponSkinBlendDialog:DrawRewards(rewards)
	for i, v in pairs(rewards) do
		if isSet(v,"convertGoods") and next(checkTable(v.convertGoods)) then
			GoodsUtils.DrawRewards({ { goodsId = v.convertGoods.goodsId, num = v.convertGoods.num } }, true)
		else
			GoodsUtils.DrawRewards({ { goodsId = v.goodsId, num = v.num } }, true)
		end
	end
end

function GachaponSkinBlendDialog:OnBtnOneNodeClick()
	local  haveNum = GoodsUtils.GetThingNo(self.skinData.oneConsume.goodsId)
	if haveNum >= self.skinData.oneConsume.num then
		self:OnBtnDraw(DrawType.One)
	else
		GameUtils.Toast(localize("道具不足"))
	end
end

function GachaponSkinBlendDialog:OnBtnTenNodeClick()
	local  haveNum = GoodsUtils.GetThingNo(self.skinData.tenConsume.goodsId)
	if haveNum >= self.skinData.tenConsume.num then
		self:OnBtnDraw(DrawType.Ten)
	else
		GameUtils.Toast(localize("道具不足"))
	end
end

function GachaponSkinBlendDialog:OnBtnStoreClick()
	local excludeIds = {{id = Constants.UITypeIds.ActivityGachaponSkinDialog}}
	---@type StoreGeneralVo
	local storeVo = CfUtils.GetCfVo(AutoIds.IdSetting601, "StoreGeneralVo", 221)
	
	CfUtils.DialogOpen(Constants.UITypeIds.UIActivityCommonShopDialog, {activityUuid = self.activityData.id , activityType = self.activityData.type,topGoods = storeVo.token, mallBgImage = storeVo.photoId },excludeIds,true)
end

function GachaponSkinBlendDialog:OnBtnMemberClick()
	local ruleId = checkNumber(self.skinData.ruleId)
	if ruleId > 0 then
		CfUtils.DialogOpen(Constants.UITypeIds.GachaponSkinBlendMember, { activityContentId = self.activityData.activityContentId,ruleId = ruleId },nil,true)
	end
end

function GachaponSkinBlendDialog:PlayNormalTimeLine(name , func)
	---@type Engine.UI.UILuaDialog
	local luaDialog = CS.Engine.UI.UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.ActivityGachaponSkinDialog)
	---@type ActivityGachaponSkinDialog
	local Env = luaDialog.Env
	local luaPath = "Game.Activity.GachaponSkin.ActivityGachaponSkinNormaTimeLine"
	local go = self:GetGameObjectByName(name)
	if isNull(go) then
		return
	end
	local isActivte = CfUtils.IsActive(go)
	if not isActivte then
		CfUtils.SetActive(go , true)
	end
	---@type ActivityGachaponSkinNormaTimeLine
	local env =  CfUtils.GetLuaScr(go , luaPath)
	Env:SetCanvasEnabled(false)
	if env then
		env:SetCamera()
		cs_coroutine.yield_return(Yielders.GetWaitForSeconds(env:GetTime() - 0.1  ))
		func()
		cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.1 ))
		CfUtils.SetActive(go.gameObject , false)
		env:DisableCamera()
	end
	Env:SetCanvasEnabled(true)
end

function GachaponSkinBlendDialog:GetGameObjectByName(name)
	---@type UnityEngine.GameObject
	local parentGo = self:GetLoadModelParentGo()
	if parentGo then
		local go =  parentGo.transform:Find(name)
		if isNull(go) then
			go = GameUtils.LoadBundleAsync(string.format("Timeline/Prefab/gacha_clothing/%s.prefab" ,name) , parentGo, false)
		end
		return go
	end
	return nil
end

function GachaponSkinBlendDialog:GetLoadModelParentGo()
	local KCookie = CS.Engine.Lib.KCookie
	local MainSceneID = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
	local sceneInstance   = SceneManagement:GetInstance():GetSceneInstance(MainSceneID)
	local gachaponCacheGo = nil
	local GameObject = CS.UnityEngine.GameObject
	local SceneManager = CS.UnityEngine.SceneManagement.SceneManager
	if not isNull(sceneInstance) then
		gachaponCacheGo = sceneInstance:GetCacheObjectByName("GachaClothing")
		if isNull(gachaponCacheGo) then
			gachaponCacheGo = GameObject("GachaClothing")
			sceneInstance:AddCacheObject(gachaponCacheGo)
			SceneManager.MoveGameObjectToScene(gachaponCacheGo, sceneInstance:GetScene())
		end
	end
	if gachaponCacheGo and (not CfUtils.IsActive(gachaponCacheGo)) then
		CfUtils.SetActive(gachaponCacheGo , true)
	end
	return gachaponCacheGo
end

